import * as T from './three.module.js';
export class LevelUpVfx{
 constructor(scene,remove){this.scene=scene;this.remove=remove;this.effects=[];}
 play(actor,level,points=1){const group=new T.Group(),mat=(color,opacity)=>new T.MeshBasicMaterial({color,transparent:true,opacity,depthWrite:false,side:T.DoubleSide,blending:T.AdditiveBlending});for(let i=0;i<3;i++){const m=new T.Mesh(new T.RingGeometry(.93,1,64),mat(i?0xffdb69:0xfff5c7,.8));m.rotation.x=-Math.PI/2;m.userData={kind:'ring',index:i};group.add(m);}const beam=new T.Mesh(new T.CylinderGeometry(.8,.55,3.7,32,1,true),mat(0xffdc75,.13));beam.position.y=1.85;beam.userData.kind='beam';group.add(beam);for(let i=0;i<44;i++){const p=new T.Mesh(new T.OctahedronGeometry(.045+(i%3)*.012),mat(i%3?0xffdc72:0xffffff,.95));p.userData={kind:'spark',i};group.add(p);}const light=new T.PointLight(0xffd474,3,5);light.position.y=1.8;group.add(light);this.scene.add(group);
 const label=document.createElement('div');label.textContent='레벨 '+level+' 달성';label.style.cssText='position:fixed;z-index:35;pointer-events:none;text-align:center;font:800 27px system-ui;color:#fff4c5;text-shadow:0 2px 3px #32200a,0 0 18px #ffb52e;transform:translate(-50%,-100%);white-space:nowrap';const sub=document.createElement('div');sub.textContent='스킬 포인트 +'+points;sub.style.cssText='font-size:15px;color:#ffdf83;margin-top:3px';label.append(sub);document.body.append(label);this.effects.push({actor,group,label,light,age:0});}
 update(dt,camera){for(let i=this.effects.length-1;i>=0;i--){const e=this.effects[i];e.age+=dt;const t=e.age,fade=Math.min(1,t/.1,Math.max(0,(2.2-t)/.65));e.group.position.set(e.actor.x,0,e.actor.z);const visible=e.actor.g?.visible!==false&&!e.actor.dead;e.group.visible=visible;e.label.style.display=visible?'':'none';e.light.intensity=3*fade;for(const m of e.group.children){const u=m.userData;if(u.kind==='ring'){const r=.55+Math.min(1,(t-u.index*.12)/.8)*1.65;m.scale.setScalar(Math.max(.1,r));m.position.y=.04+u.index*.12+Math.min(t,.8)*u.index*.5;m.material.opacity=Math.max(0,1-t/1.5)*.85;}if(u.kind==='beam'){m.scale.set(1,Math.min(1,t/.18),1);m.material.opacity=.15*fade*Math.max(0,1-t/1.6);}if(u.kind==='spark'){const a=u.i*2.4+t*.8,h=(t*.95+u.i/44)%1;m.position.set(Math.cos(a)*(.5+h*.5),.15+h*3.6,Math.sin(a)*(.5+h*.5));m.rotation.set(t+u.i,t*2,0);m.material.opacity=Math.sin(h*Math.PI)*fade;}}
 const p=new T.Vector3(e.actor.x,3.1+Math.min(t,1)*.3,e.actor.z).project(camera);e.label.style.left=(p.x+1)*innerWidth/2+'px';e.label.style.top=(1-p.y)*innerHeight/2+'px';e.label.style.opacity=fade;if(t>=2.2){this.remove(e.group);e.label.remove();this.effects.splice(i,1);}}}
 clear(){for(const e of this.effects){this.remove(e.group);e.label.remove();}this.effects=[];}
}
